import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        print(-1)
        return

    n = int(data[0])
    coins = list(map(int, data[1:1+n]))
    amount = int(data[1+n])

    if amount == 0:
        print(0)
        return

    if n == 0 or amount < 0:
        print(-1)
        return

    coins = [c for c in coins if c > 0]
    if not coins:
        print(-1)
        return

    dp = [float('inf')] * (amount + 1)
    dp[0] = 0

    for i in range(1, amount + 1):
        for coin in coins:
            if coin <= i and dp[i - coin] != float('inf'):
                dp[i] = min(dp[i], dp[i - coin] + 1)

    if dp[amount] == float('inf'):
        print(-1)
    else:
        print(dp[amount])

if __name__ == "__main__":
    main()
